#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <functional>
#include <utility>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    long long k;
    cin >> n >> m >> k;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<pair<int, long long>>> adj(n + 1);
    for (const vector<long long>& e : edges) adj[e[0]].push_back({(int)e[1], e[2]});
    const long long INF = 1000000000000000000LL;
    vector<long long> dist(n + 1, INF);
    dist[k] = 0;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> heap;
    heap.push({0, (int)k});
    while (!heap.empty()) {
        pair<long long, int> top = heap.top();
        heap.pop();
        int u = top.second;
        if (top.first > dist[u]) continue;
        for (const auto& edge : adj[u]) {
            long long next = top.first + edge.second;
            if (next < dist[edge.first]) {
                dist[edge.first] = next;
                heap.push({next, edge.first});
            }
        }
    }
    long long answer = 0;
    for (int v = 1; v <= n; v++) answer = max(answer, dist[v]);
    cout << (answer >= INF ? -1 : answer) << "\n";

    return 0;
}

