import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[][] edges = new long[(int) m][3];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        List<List<long[]>> adj = new ArrayList<>();
        for (int v = 0; v <= nodes; v++) adj.add(new ArrayList<>());
        for (long[] e : edges) adj.get((int) e[0]).add(new long[] {e[1], e[2]});
        long INF = 1000000000000000000L;
        long[] dist = new long[nodes + 1];
        Arrays.fill(dist, INF);
        dist[(int) k] = 0;
        PriorityQueue<long[]> heap = new PriorityQueue<>((p, q) -> Long.compare(p[0], q[0]));
        heap.add(new long[] {0, k});
        while (!heap.isEmpty()) {
            long[] top = heap.poll();
            int u = (int) top[1];
            if (top[0] > dist[u]) continue;
            for (long[] edge : adj.get(u)) {
                int v = (int) edge[0];
                long next = top[0] + edge[1];
                if (next < dist[v]) {
                    dist[v] = next;
                    heap.add(new long[] {next, v});
                }
            }
        }
        long answer = 0;
        for (int v = 1; v <= nodes; v++) answer = Math.max(answer, dist[v]);
        System.out.println(answer >= INF ? -1 : answer);
    }
}
